import {
  ArrowDown01Icon,
  ArrowUp01Icon,
  Cancel01Icon,
  Edit01Icon,
  PlusSignIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { AnimatePresence, motion } from "motion/react";
import type { FormEvent, RefObject } from "react";
import type { SpaceKind, StoredSpace } from "../../lib/libraryApi";
import { Button } from "../../ui/Button";
import { cx } from "../../ui/cx";
import { IconButton } from "../../ui/IconButton";
import { SpaceMark } from "../../ui/SpaceMark";
import { countClass, rowClass } from "./Sidebar";

const tool =
  "grid flex-none place-items-center rounded-[5px] p-[3px] text-muted cursor-pointer transition-[color,background-color] duration-150 ease-[ease]";

export type SpaceRowActions = {
  select: (space: StoredSpace) => void;
  cycleColor: (space: StoredSpace) => void;
  move: (space: StoredSpace, direction: -1 | 1) => void;
  startRename: (space: StoredSpace) => void;
  rename: (space: StoredSpace, name: string) => void;
  cancelRename: () => void;
  remove: (space: StoredSpace) => void;
};

export type SpaceDraft = {
  isOpen: boolean;
  name: string;
  kind: SpaceKind;
  query: string;
  nameInputRef: RefObject<HTMLInputElement | null>;
  toggle: () => void;
  setName: (name: string) => void;
  setKind: (kind: SpaceKind) => void;
  cancel: () => void;
  submit: (event: FormEvent<HTMLFormElement>) => void;
};

export function SpacesSection({
  spaces,
  activeSpaceId,
  activeCount,
  renaming,
  actions,
  draft,
}: {
  spaces: StoredSpace[];
  activeSpaceId: string | null;
  activeCount: number;
  renaming: {
    id: string | null;
    draft: string;
    setDraft: (draft: string) => void;
    inputRef: RefObject<HTMLInputElement | null>;
  };
  actions: SpaceRowActions;
  draft: SpaceDraft;
}) {
  return (
    <div className="flex flex-col gap-0.5">
      <div className="flex h-7 items-center justify-between px-2.5 font-body text-[12px] leading-4 font-medium tracking-[0.02em] text-muted">
        <span>Spaces</span>
        {/* The + sits flush with the row edge, as in Paper. */}
        <IconButton label="Add a Space" size="xs" className="-mr-[3px]" onClick={draft.toggle}>
          <HugeiconsIcon icon={PlusSignIcon} size={14} />
        </IconButton>
      </div>
      <div className="grid min-w-0 grid-cols-[minmax(0,1fr)] gap-0.5">
        {spaces.map((space) => {
          const selected = activeSpaceId === space.id;
          return (
            <div
              key={space.id}
              className={cx(
                rowClass,
                "group/space text-[14px]",
                selected ? "font-semibold text-ink-active" : "text-ink-soft hover:text-ink",
              )}
            >
              <Button
                className="mr-2.5 grid size-4 flex-none place-items-center p-0 cursor-pointer focus-visible:outline-offset-2!"
                data-tooltip={`Change color (now ${space.color})`}
                aria-label={`Change color of ${space.name}`}
                onClick={() => actions.cycleColor(space)}
              >
                <span className="block" aria-hidden="true">
                  <SpaceMark color={space.color} />
                </span>
              </Button>
              {renaming.id === space.id ? (
                <input
                  ref={renaming.inputRef}
                  className="min-h-[26px] w-full min-w-0 flex-1 rounded-lg border border-accent bg-surface px-2 text-[13px] text-ink"
                  value={renaming.draft}
                  aria-label={`Rename ${space.name}`}
                  maxLength={80}
                  onChange={(event) => renaming.setDraft(event.target.value)}
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => {
                    event.stopPropagation();
                    if (event.key === "Enter") actions.rename(space, renaming.draft);
                    else if (event.key === "Escape") actions.cancelRename();
                  }}
                  // Blur commits, matching Finder/Explorer/VS Code rename fields:
                  // silently discarding typed text loses work, while an
                  // accidental save is one rename away from fixed.
                  onBlur={() => actions.rename(space, renaming.draft)}
                />
              ) : (
                <Button
                  className="flex min-w-0 flex-1 items-center gap-2.5 p-0 text-left cursor-pointer focus-visible:outline-offset-2!"
                  onClick={() => actions.select(space)}
                  aria-pressed={selected}
                >
                  <span className="min-w-0 flex-1 overflow-x-auto overflow-y-hidden whitespace-nowrap [overscroll-behavior-inline:contain] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
                    {space.name}
                  </span>
                  {/* The hover tools take the count's place. */}
                  <span
                    className={cx(
                      countClass,
                      "group-hover/space:hidden group-focus-within/space:hidden",
                    )}
                  >
                    {(space.itemCount ?? (selected ? activeCount : undefined))?.toLocaleString()}
                  </span>
                </Button>
              )}
              <span className="flex w-0 flex-none overflow-hidden opacity-0 transition-opacity duration-150 ease-[ease] group-hover/space:ml-2.5 group-hover/space:w-[72px] group-hover/space:opacity-100 group-focus-within/space:ml-2.5 group-focus-within/space:w-[72px] group-focus-within/space:opacity-100">
                <Button
                  className={cx(tool, "hover:text-ink")}
                  aria-label={`Move ${space.name} up`}
                  data-tooltip="Move Space up"
                  onClick={(event) => {
                    event.stopPropagation();
                    actions.move(space, -1);
                  }}
                >
                  <HugeiconsIcon icon={ArrowUp01Icon} size={12} />
                </Button>
                <Button
                  className={cx(tool, "hover:text-ink")}
                  aria-label={`Move ${space.name} down`}
                  data-tooltip="Move Space down"
                  onClick={(event) => {
                    event.stopPropagation();
                    actions.move(space, 1);
                  }}
                >
                  <HugeiconsIcon icon={ArrowDown01Icon} size={12} />
                </Button>
                <Button
                  className={cx(tool, "hover:text-ink")}
                  aria-label={`Rename ${space.name}`}
                  data-tooltip="Rename Space"
                  onClick={(event) => {
                    event.stopPropagation();
                    actions.startRename(space);
                  }}
                >
                  <HugeiconsIcon icon={Edit01Icon} size={12} />
                </Button>
                <Button
                  className={cx(tool, "hover:text-[#e08a5e]")}
                  aria-label={`Delete ${space.name}`}
                  data-tooltip="Delete Space"
                  onClick={(event) => {
                    event.stopPropagation();
                    actions.remove(space);
                  }}
                >
                  <HugeiconsIcon icon={Cancel01Icon} size={12} />
                </Button>
              </span>
            </div>
          );
        })}
      </div>
      <AnimatePresence mode="wait">
        {draft.isOpen && (
          <motion.form
            key="space-form"
            className="grid gap-2 px-2.5 pt-1.5 pb-2.5"
            initial={{ opacity: 0, transform: "translateY(-6px)" }}
            animate={{ opacity: 1, transform: "translateY(0)" }}
            exit={{ opacity: 0, transform: "translateY(-4px)" }}
            transition={{ duration: 0.2, ease: [0.23, 1, 0.32, 1] }}
            onSubmit={draft.submit}
          >
            <input
              ref={draft.nameInputRef}
              className="min-h-[33px] w-full rounded-lg border border-border bg-surface px-2.5 text-[13px] text-ink outline-none! focus:border-accent"
              value={draft.name}
              onChange={(event) => draft.setName(event.target.value)}
              placeholder={
                draft.kind === "smart" && draft.query.trim()
                  ? `Save “${draft.query.trim()}” as…`
                  : "Name this space"
              }
              aria-label="Space name"
              maxLength={80}
            />
            {/* Native radios rather than role="radio" buttons: the group gets
            arrow-key selection, one tab stop and group semantics from the
            platform instead of from ARIA we would then have to maintain. */}
            <fieldset className="m-0 grid min-w-0 grid-cols-2 gap-[3px] rounded-button border border-border bg-surface p-[3px]">
              <legend className="visually-hidden">How this Space fills</legend>
              {(["smart", "regular"] as const).map((kind) => (
                <label
                  key={kind}
                  className={cx(
                    // The real input is clipped, so the label draws its focus ring.
                    "flex items-center justify-center rounded-md py-1.5 text-[12px] cursor-pointer transition-[color,background-color] duration-150 ease-[ease] has-focus-visible:outline-2 has-focus-visible:outline-offset-3 has-focus-visible:outline-accent",
                    draft.kind === kind
                      ? "bg-accent-soft font-semibold text-accent"
                      : "text-muted hover:text-ink",
                  )}
                >
                  <input
                    type="radio"
                    name="space-kind"
                    className="visually-hidden"
                    value={kind}
                    checked={draft.kind === kind}
                    aria-describedby="space-kind-hint"
                    onChange={() => draft.setKind(kind)}
                  />
                  {kind === "smart" ? "Smart" : "Regular"}
                </label>
              ))}
            </fieldset>
            <p className="m-0 text-[11px] leading-[1.45] text-muted" id="space-kind-hint">
              {draft.kind === "regular"
                ? "Holds only the items you file into it. Open an item and pick a Space to add it."
                : draft.query.trim()
                  ? "A Smart Space that updates automatically as items match this search."
                  : "An empty Smart Space matches everything you have saved."}
            </p>
            <div className="flex items-center justify-between gap-2.5">
              <Button variant="text" onClick={draft.cancel}>
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                Create Space
              </Button>
            </div>
          </motion.form>
        )}
      </AnimatePresence>
    </div>
  );
}

import { ArrowLeft01Icon, ViewSidebarLeftIcon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { cx } from "../../ui/cx";
import { Surface } from "../../ui/Surface";

// Opens the closed sidebar from the toolbar's left end, in the search chip's glass.
export function SidebarOpenButton({ edgeToggle, onOpen }: { edgeToggle: boolean; onOpen: () => void }) {
  return (
    <Surface
      liquid
      render={<button type="button" />}
      className={cx(
        "sidebar-toggle absolute top-1/2 left-0 grid size-[34px] -translate-y-1/2 place-items-center rounded-[17px] p-0 text-ink-soft cursor-pointer transition-[color,scale] duration-180 ease-[ease] hover:text-ink active:scale-96",
        edgeToggle && "wide:hidden",
      )}
      aria-label="Open sidebar"
      data-tooltip="Open sidebar"
      aria-expanded={false}
      aria-controls="library-navigation"
      onClick={onOpen}
    >
      <HugeiconsIcon icon={ViewSidebarLeftIcon} size={17} />
    </Surface>
  );
}

// Settings → Appearance "Edge grip": the sidebar opens and closes from the
// library frame's left edge. Nothing shows at rest while the sidebar is open;
// hovering or focusing the edge raises a grip and a knob. Closed, a faint grip
// stays on the window's edge so there is always a way back. Wide windows only;
// narrow ones keep their buttons.
export function SidebarEdgeGrip({ isOpen, onToggle }: { isOpen: boolean; onToggle: () => void }) {
  const label = isOpen ? "Close sidebar" : "Open sidebar";
  return (
    <button
      type="button"
      className={cx(
        "group absolute top-[calc(4px+var(--spacing-titlebar))] bottom-5 left-0 z-32 hidden border-0 bg-transparent p-0 cursor-pointer transition-[left] duration-300 ease-[cubic-bezier(0.4,0,0.2,1)] focus-visible:outline-none! wide:block",
        // The bar sits 5px inside the frame either way: just right of the open
        // sidebar, or just inside the window's edge while it is closed.
        isOpen ? "left-[calc(var(--spacing-sidebar)-4px)] w-[18px]" : "w-3.5",
      )}
      aria-label={label}
      aria-expanded={isOpen}
      aria-controls="library-navigation"
      onClick={onToggle}
    >
      <span
        className={cx(
          "absolute top-1/2 h-10 w-1 -translate-y-1/2 rounded-[2px] bg-ink transition-[opacity,height] duration-180 ease-[ease] group-hover:h-14 group-hover:opacity-60 group-focus-visible:h-14 group-focus-visible:opacity-60",
          isOpen ? "left-[9px] opacity-0" : "left-[5px] opacity-22",
        )}
      />
      <Surface
        render={<span />}
        className={cx(
          "pointer-events-none absolute top-1/2 -mt-3.5 grid size-7 place-items-center rounded-full text-ink opacity-0 scale-85 transition-[opacity,scale] duration-180 ease-[ease] group-hover:pointer-events-auto group-hover:opacity-100 group-hover:scale-100 group-focus-visible:pointer-events-auto group-focus-visible:opacity-100 group-focus-visible:scale-100",
          isOpen ? "left-[26px]" : "left-[22px] [&_svg]:rotate-180",
        )}
        data-tooltip={`${label} · Ctrl+\\`}
      >
        <HugeiconsIcon icon={ArrowLeft01Icon} size={14} strokeWidth={2} />
      </Surface>
    </button>
  );
}

