// Tiny CDP helper for spike/verification scripts (scratch, not committed).
import { mkdirSync } from "node:fs";
import { join } from "node:path";
export async function connect(port = "9333", out = "") {
  if (out) mkdirSync(out, { recursive: true });
  const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  const page = targets.find((t: any) => t.type === "page" && t.url.startsWith("app://local/"));
  const socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r, j) => { socket.onopen = r; socket.onerror = j; });
  let seq = 0;
  const pending = new Map<number, any>();
  const logs: string[] = [];
  socket.onmessage = (e) => {
    const m = JSON.parse(e.data as string);
    if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.j(new Error(m.error.message)) : p.r(m.result); return; }
    if (m.method === "Runtime.consoleAPICalled") logs.push(`[${m.params.type}] ${m.params.args.map((a: any) => a.value ?? a.description ?? "").join(" ")}`);
    if (m.method === "Runtime.exceptionThrown") logs.push(`[exception] ${m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text}`);
  };
  const send = (method: string, params: any = {}) => new Promise<any>((r, j) => { const id = ++seq; pending.set(id, { r, j }); socket.send(JSON.stringify({ id, method, params })); });
  await send("Runtime.enable");
  const ev = async (expression: string) => {
    const res = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    if (res.exceptionDetails) throw new Error(res.exceptionDetails.exception?.description ?? res.exceptionDetails.text);
    return res.result.value;
  };
  const until = async (expression: string, timeoutMs = 8000) => {
    const end = Date.now() + timeoutMs;
    while (Date.now() < end) { if (await ev(`Boolean(${expression})`)) return true; await new Promise((r) => setTimeout(r, 100)); }
    throw new Error(`never held: ${expression}`);
  };
