await settle();
await c.shot("02-window-close-hover.png");
report.windowControls = await c.ev(`[...document.querySelectorAll('[aria-label="Minimize"], [aria-label="Maximize or restore"], [aria-label="Close window"]')].map(e => { const r = e.getBoundingClientRect(); return [e.getAttribute("aria-label"), Math.round(r.x), Math.round(r.width), Math.round(r.height), getComputedStyle(e).backgroundColor]; })`);
report.dragRegion = await c.ev(`[...document.querySelectorAll("div")].filter(e => getComputedStyle(e).getPropertyValue("-webkit-app-region") === "drag").map(e => { const r = e.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height), getComputedStyle(e).zIndex]; })`);

await hoverAt(`[...document.querySelectorAll("button")].find(b => b.textContent.includes("Moodboard"))`);
await settle();
await c.shot("03-space-row-hover.png");

await clickAt(visible(`[aria-label="Close sidebar"]`));
await c.move(900, 500);
await settle();
await c.shot("04-closed.png");
await hoverAt(visible(`[aria-label="Open sidebar"]`));
await tooltip("Open sidebar");
await settle();
report.tooltipLiquid = await c.ev(`[...document.querySelectorAll("body *")].find(e => e.textContent === "Open sidebar" && !e.closest("button") && e.matches(".glass, .css-glass"))?.className`);
report.toggleLiquid = await c.ev(`document.querySelector('[aria-label="Open sidebar"]').hasAttribute("data-liquid")`);
