await settle();
await hoverAt(visible(`[aria-controls="library-navigation"][aria-expanded="true"]`));
await settle();
await hoverAt(visible(`[data-tooltip^="Close sidebar ·"]`));
await tooltip("Close sidebar · Ctrl+\\");
await settle();
await c.shot("06-edge-hover.png");
await c.ev(`localStorage.removeItem("appearance"); true`);

console.log(JSON.stringify(report, null, 1), c.logs.filter((l) => l.startsWith("[error]") || l.startsWith("[exception]")).join("\n"));
