229	function formatItemDate(timestamp: number) {
230	  const date = new Date(timestamp);
231	  const age = Date.now() - date.getTime();
232	  if (age < 60 * 60 * 1000) return "Just now";
233	  if (age < 24 * 60 * 60 * 1000) return "Today";
234	  return date.toLocaleDateString(undefined, { month: "short", day: "2-digit" });
235	}
