237	function formatByteSize(bytes: number) {
238	  if (bytes < 1024) return `${bytes} B`;
239	  const units = ["KB", "MB", "GB"];
240	  let value = bytes / 1024;
241	  let unit = 0;
242	  while (value >= 1024 && unit < units.length - 1) {
243	    value /= 1024;
244	    unit += 1;
245	  }
246	  return `${value.toFixed(value >= 10 ? 0 : 1)} ${units[unit]}`;
247	}
