335	function readImageDimensions(src: string): Promise<{ width: number; height: number } | undefined> {
336	  return new Promise((resolve) => {
337	    const image = new Image();
338	    image.onload = () => {
339	      const width = image.naturalWidth;
340	      const height = image.naturalHeight;
341	      resolve(width > 0 && height > 0 ? { width, height } : undefined);
342	    };
343	    image.onerror = () => resolve(undefined);
344	    image.src = src;
345	  });
346	}
