374	    Number.isInteger(item.metadata.pdfPageCount) &&
375	    item.metadata.pdfPageCount > 0
376	      ? item.metadata.pdfPageCount
377	      : undefined;
378	
379	  const remoteImage = Array.isArray(item.metadata.imageUrls)
380	    ? item.metadata.imageUrls
381	        .map(safePublicImageUrl)
382	        .find((value): value is string => value !== undefined)
383	    : undefined;
384	  const indexedImageDimensions = Array.isArray(item.metadata.imageDimensions)
385	    ? item.metadata.imageDimensions.find((value): value is Record<string, unknown> => {
386	        if (!value || typeof value !== "object") return false;
387	        const record = value as Record<string, unknown>;
388	        return (
389	          (!remoteImage || record.url === remoteImage) &&
390	          positiveNumber(record.width) !== undefined &&
391	          positiveNumber(record.height) !== undefined
392	        );
393	      })
394	    : undefined;
395	  const mediaWidth =
396	    positiveNumber(item.metadata.mediaWidth) ?? positiveNumber(indexedImageDimensions?.width);
397	  const mediaHeight =
398	    positiveNumber(item.metadata.mediaHeight) ?? positiveNumber(indexedImageDimensions?.height);
399	  const storedAspectRatio = positiveNumber(item.metadata.mediaAspectRatio);
400	  // A new image's thumbnail is made in the background, so until it lands (or
401	  // if it never can be) the card shows the original instead of a placeholder.
402	  const image =
403	    (await assetUrl(item.thumbnailPath ?? (kind === "Image" ? item.localAssetPath : null))) ??
404	    remoteImage ??
405	    videoLink?.posterUrl;
406	  // For an image this is the original file, which the item view swaps in once
407	  // the user zooms past fit. It is not a fallback thumbnail.
408	  const fileUrl =
409	    kind === "PDF" || kind === "Video" || kind === "Image"
410	      ? await assetUrl(item.localAssetPath)
411	      : undefined;
412	  const source = social
413	    ? `X${social.authorHandle ? ` · @${social.authorHandle.replace(/^@/u, "")}` : ""}`
414	    : item.sourceLabel || item.sourceUrl || "Quick note";
415	
416	  const isQuote = kind === "Quote";
417	  const noteBody =
418	    kind === "Note" && "body" in item && typeof item.body === "string"
419	      ? normalizeNoteBody(item.body)
420	      : undefined;
421	  const rawTitle = item.title?.trim() || "Untitled note";
422	  // The backend already stored `markdownToPlainText(body)` as the
423	  // description, so a note's plain text arrives ready to read. Projecting the
424	  // body again here would only ever disagree with the stored row, and would
425	  // eat the brackets in prose that happens to look like a link.
426	  const rawDescription =
427	    item.description?.trim() ||
428	    item.ocrText?.trim().slice(0, 180) ||
429	    (isQuote ? "" : "Saved to your mind.");
430	
431	  return {
432	    id: item.id,
433	    kind,
434	    title: rawTitle,
435	    description: social?.text?.trim() || rawDescription,
436	    noteBody,
