450	    durationSeconds: positiveNumber(item.metadata.durationSeconds),
451	    fileSizeBytes: positiveNumber(item.metadata.fileSizeBytes),
452	    readingMinutes: positiveNumber(item.metadata.readingMinutes),
453	    fileUrl,
454	    imageAlt: item.title?.trim() || undefined,
