456	    post: social ? postFallbackFromMetadata(social) : undefined,
457	    accent: isQuote ? "paper-yellow" : undefined,
458	    archived: item.archived,
459	    processing,
460	    hasArticleContent,
461	    video: videoLink ?? undefined,
462	  };
463	}
