2735	  // The chips toggle from live membership, so this has to stay a stable
2736	  // callback: the overlay actions memo closes over it, and a plain function
2737	  // would leave that memo holding a pre-toggle membership read and turn
2738	  // "Remove from" into a second add.
2739	  //
2740	  // The direction is applied before the write rather than after it, because a
2741	  // second click while the first write is in flight has to reverse the first
2742	  // instead of repeating it. Two writes for one Space are chained so the
2743	  // reversal cannot land before the write it reverses.
2744	  const spaceWritesRef = useRef<Map<string, Promise<void>>>(new Map());
2745	  // Bumped by every chip toggle. A membership read already in flight carries the
2746	  // value it saw here and drops its result if a toggle has landed since, so an
2747	  // older read cannot roll back the chip the user just changed.
2748	  const spaceMembershipEpochRef = useRef(0);
2749	  const handleToggleItemInSpace = useCallback(
2750	    async (item: LibraryItem, spaceId: string) => {
2751	      const itemId = String(item.id);
2752	      const wasMember = itemSpaceIds.includes(spaceId);
2753	      // `adding` is the state being moved to, not the one being left. Naming it
2754	      // after the destination keeps the write and the optimistic apply reading the
2755	      // same way round, which is the trap the previous `member` name walked into.
2756	      const adding = !wasMember;
2757	      const show = (next: boolean) => {
2758	        setItemSpaceIds((current) => {
2759	          if (next) return current.includes(spaceId) ? current : [...current, spaceId];
2760	          return current.filter((id) => id !== spaceId);
2761	        });
2762	      };
2763	      if (!canUseDesktopBackend) {
2764	        // Preview keeps membership in local state and an effect mirrors that into
2765	        // itemSpaceIds, so there is no write to make and none to chain.
2766	        setLocalSpaceItems((current) => {
2767	          const next = new Map(current);
2768	          const members = new Set(next.get(spaceId) ?? []);
2769	          if (adding) members.add(itemId);
2770	          else members.delete(itemId);
2771	          next.set(spaceId, members);
2772	          return next;
2773	        });
2774	        return;
2775	      }
2776	
2777	      spaceMembershipEpochRef.current += 1;
2778	      show(adding);
2779	      const write = (spaceWritesRef.current.get(spaceId) ?? Promise.resolve())
2780	        .then(async () => {
2781	          if (adding) await addSpaceItem(spaceId, itemId);
2782	          else await removeSpaceItem(spaceId, itemId);
2783	          // The open Space lists its own members, so its grid has to re-read.
2784	          if (activeSpaceId === spaceId) loadItemsRef.current();
2785	        })
2786	        .catch(() => {
2787	          // A failed write must not leave the chip claiming a membership the
2788	          // library does not have.
2789	          show(wasMember);
2790	          setSidebarActionError(
2791	            adding
2792	              ? "Couldn’t add this item to the Space."
2793	              : "Couldn’t remove this item from the Space.",
2794	          );
2795	        })
2796	        .finally(() => {
2797	          if (spaceWritesRef.current.get(spaceId) === write) spaceWritesRef.current.delete(spaceId);
2798	        });
2799	      spaceWritesRef.current.set(spaceId, write);
2800	      await write;
2801	    },
2802	    [activeSpaceId, canUseDesktopBackend, itemSpaceIds],
2803	  );
