import re,glob
for p in glob.glob("src/features/**/*.ts",recursive=True):
    lines=open(p,encoding="utf8").read().split("\n"); changed=False
    for i,l in enumerate(lines):
        st=l.strip()
        if "Ref.current" in l and (st.startswith("[") or st.startswith("}, [")) and (st.endswith("]);") or st.endswith("],")):
            new=re.sub(r"(\w+Ref)\.current(?:\??\.\w+)?", r"\1", l)
            # dedupe entries
            pre,arr,post=re.match(r"^(.*?\[)(.*)(\].*)$",new).groups()
            seen=[]; 
            for x in [a.strip() for a in arr.split(",") if a.strip()]:
                if x not in seen: seen.append(x)
            lines[i]=pre+", ".join(seen)+post; changed=True
    if changed: open(p,"w",encoding="utf8",newline="").write("\n".join(lines)); print(p)
EOF
