/* The stage covers the frame under the toolbar. It holds the library scroller
   and, with liquid glass, the canvas that draws it (LiquidGlass.tsx). The
   scroller is placed absolutely so it lands in the same spot either way. */
.library-stage {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}
/* Sized to the window, not the stage. Resizing a WebGPU canvas stalls the GPU
   for tens of milliseconds, and the stage resizes every frame of a sidebar
   slide; the window rarely does. The extra edge is clipped. */
.library-stage .liquid-glass-canvas {
  width: 100vw;
  height: 100vh;
}
.library-stage .liquid-glass-content {
  background: var(--stage-background);
}
/* The scroller reaches past the toolbar and bottom padding, nearly to the
   frame's edges, where LibraryEdgeFade blurs the cards out. The grid's padding
   puts the rows back where they rest. */
.library-scroll {
  --scroll-reach-top: 12px;
  --scroll-reach-bottom: 20px;
  position: absolute;
  top: calc(var(--library-top) - var(--scroll-reach-top));
  right: var(--main-pad-x);
  bottom: calc(var(--main-pad-bottom) - var(--scroll-reach-bottom));
  left: var(--main-pad-x);
  overflow: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
/* The first row rests at the toolbar's top, under the floating search chip,
   and scrolls no higher; the last row ends above the bottom blur. Paper 1.3:
   with a query pinned, the 44px filter row puts the first card 100px below
   the toolbar's top. */
.library-scroll .library-grid {
  padding-top: var(--scroll-reach-top);
  padding-bottom: calc(var(--scroll-reach-bottom) + 36px);
}
.library-scroll.has-pinned-query .library-grid {
  padding-top: calc(var(--scroll-reach-top) + 100px);
}
/* The grid/list toggle floats centred over the bottom blur. */
.view-dock {
  position: absolute;
  bottom: 16px;
  left: 50%;
  z-index: 2;
  translate: -50% 0;
