206	// Captures the card and its media box before selection state changes, so the
207	// overlay's opening flight starts from the card's exact position.
208	function cardRectsFor(card: HTMLElement): SourceRects {
209	  const cardRect = card.getBoundingClientRect();
210	  const mediaRect = card.querySelector<HTMLElement>(".library-card-media")?.getBoundingClientRect();
211	  return {
212	    card: {
213	      left: cardRect.left,
214	      top: cardRect.top,
215	      width: cardRect.width,
216	      height: cardRect.height,
217	    },
218	    media: mediaRect
219	      ? {
220	          left: mediaRect.left,
221	          top: mediaRect.top,
222	          width: mediaRect.width,
223	          height: mediaRect.height,
224	        }
225	      : { left: cardRect.left, top: cardRect.top, width: cardRect.width, height: 0 },
226	  };
227	}
