157	export function formatFileSize(bytes: number): string {
158	  if (bytes < 1024) return `${bytes} B`;
159	  const units = ["KB", "MB", "GB", "TB"];
160	  let value = bytes / 1024;
161	  let unit = 0;
162	  while (value >= 1024 && unit < units.length - 1) {
163	    value /= 1024;
164	    unit += 1;
165	  }
166	  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`;
167	}
