171	  const hours = Math.floor(seconds / 3600);
172	  const minutes = Math.floor((seconds % 3600) / 60);
173	  const rest = String(seconds % 60).padStart(2, "0");
174	  return hours > 0 ? `${hours}:${String(minutes).padStart(2, "0")}:${rest}` : `${minutes}:${rest}`;
175	}
