304	let xWidgetsPromise: Promise<void> | null = null;
305	const X_WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
306	
307	function loadXWidgets() {
308	  if (typeof window === "undefined" || window.twttr?.widgets) return Promise.resolve();
309	  if (xWidgetsPromise) return xWidgetsPromise;
310	
311	  xWidgetsPromise = new Promise<void>((resolve, reject) => {
312	    const existing = document.querySelector<HTMLScriptElement>("#twitter-wjs");
313	    const script = existing ?? document.createElement("script");
314	    let pollId: number | undefined;
315	    let timeoutId: number | undefined;
316	    let settled = false;
317	
318	    const finish = (error?: Error) => {
319	      if (settled) return;
320	      settled = true;
321	      if (pollId !== undefined) window.clearInterval(pollId);
322	      if (timeoutId !== undefined) window.clearTimeout(timeoutId);
323	      if (error) reject(error);
324	      else resolve();
325	    };
326	
327	    const checkReady = () => {
328	      if (window.twttr?.widgets) finish();
329	    };
330	
331	    const handleLoad = () => {
332	      checkReady();
333	      window.setTimeout(checkReady, 0);
334	    };
335	    const handleError = () => finish(new Error("X widgets could not be loaded."));
336	
337	    script.addEventListener("load", handleLoad, { once: true });
338	    script.addEventListener("error", handleError, { once: true });
339	
340	    if (!existing) {
341	      script.id = "twitter-wjs";
342	      script.src = X_WIDGETS_SRC;
343	      script.async = true;
344	      script.charset = "utf-8";
345	      document.head.appendChild(script);
346	    }
347	
348	    checkReady();
349	    pollId = window.setInterval(checkReady, 100);
350	    timeoutId = window.setTimeout(() => finish(new Error("X widgets timed out.")), 15000);
351	  });
352	
353	  return xWidgetsPromise;
354	}
