356	function waitForXWidget(root: HTMLElement, timeoutMs = 8000): Promise<boolean> {
357	  return new Promise((resolve) => {
358	    let settled = false;
359	    let observer: MutationObserver | null = null;
360	    let timeoutId: number | undefined;
361	
362	    const finish = (loaded: boolean) => {
363	      if (settled) return;
364	      settled = true;
365	      observer?.disconnect();
366	      if (timeoutId !== undefined) window.clearTimeout(timeoutId);
367	      resolve(loaded);
368	    };
369	
370	    const watchWidget = () => {
371	      const iframe = root.querySelector<HTMLIFrameElement>("iframe");
372	      if (!iframe) return;
373	
374	      // X replaces the blockquote with its official cross-origin iframe. The
375	      // iframe load event is not a reliable readiness signal here: cached
376	      // frames can finish before a listener is attached, and some browsers do
377	      // not surface a second load event for an already-created frame. Seeing
378	      // the official iframe is the stable signal that widgets.js transformed
379	      // this embed. Do not wait for requestAnimationFrame here: the preview
380	      // can be backgrounded, and browsers throttle animation frames in that
381	      // state even though the cross-origin iframe has already loaded.
382	      finish(true);
383	    };
384	
385	    observer = new MutationObserver(watchWidget);
386	    observer.observe(root, { childList: true, subtree: true });
387	    watchWidget();
388	    timeoutId = window.setTimeout(() => finish(false), timeoutMs);
389	  });
390	}
