392	export function XPostEmbed({ social, fallback }: { social: XPostMetadata; fallback: ReactNode }) {
393	  const nativeRef = useRef<HTMLDivElement>(null);
394	  const [shouldLoad, setShouldLoad] = useState(false);
395	  const [embedHtml, setEmbedHtml] = useState<string | undefined>(social.embedHtml);
396	  const [status, setStatus] = useState<"idle" | "loading" | "ready" | "failed">("idle");
397	
398	  useEffect(() => {
399	    setEmbedHtml(social.embedHtml);
400	    setStatus("idle");
401	  }, [social.embedHtml]);
402	
403	  useEffect(() => {
404	    if (!shouldLoad) return;
405	    let cancelled = false;
406	    setStatus("loading");
407	
408	    if (social.embedHtml) {
409	      setEmbedHtml(social.embedHtml);
410	      return () => {
411	        cancelled = true;
412	      };
413	    }
414	
415	    fetch(xPostOEmbedUrl(social.postUrl), { headers: { Accept: "application/json" } })
416	      .then((response) => {
417	        if (!response.ok) throw new Error(`X oEmbed returned HTTP ${response.status}.`);
418	        return response.json() as Promise<unknown>;
419	      })
420	      .then((payload) => {
421	        if (cancelled) return;
422	        const normalized = normalizeXPostOEmbed(
423	          social.postUrl,
424	          payload as Parameters<typeof normalizeXPostOEmbed>[1],
425	        );
426	        if (!normalized?.embedHtml) throw new Error("X did not return embed markup.");
427	        setEmbedHtml(normalized.embedHtml);
428	      })
429	      .catch(() => {
430	        if (!cancelled) setStatus("failed");
431	      });
432	
433	    return () => {
434	      cancelled = true;
435	    };
436	  }, [shouldLoad, social.embedHtml, social.postUrl]);
437	
438	  useEffect(() => {
439	    if (!shouldLoad) return;
440	    const root = nativeRef.current;
441	    if (!root || !embedHtml) return;
442	
443	    root.innerHTML = embedHtml;
444	    const updateEmbedWidth = () => {
445	      const width = Math.min(550, Math.max(280, Math.floor(root.getBoundingClientRect().width)));
446	      const iframe = root.querySelector<HTMLIFrameElement>("iframe");
447	
448	      if (iframe) {
449	        // The iframe itself is width: 100%; changing its URL after X has
450	        // rendered causes the widget to reload and can create a resize loop.
451	        // Its document receives the new viewport width through the iframe box.
452	        return;
453	      }
454	
455	      root
456	        .querySelector<HTMLElement>("blockquote.twitter-tweet")
457	        ?.setAttribute("data-width", String(width));
458	    };
459	
460	    updateEmbedWidth();
461	    const resizeObserver =
462	      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(updateEmbedWidth);
463	    resizeObserver?.observe(root);
464	    window.addEventListener("resize", updateEmbedWidth);
465	    let cancelled = false;
466	    loadXWidgets()
467	      .then(async () => {
468	        if (cancelled) return;
469	        const widgetLoad = waitForXWidget(root);
470	        window.twttr?.widgets?.load(root);
471	        const loaded = await widgetLoad;
472	        if (!cancelled) setStatus(loaded ? "ready" : "failed");
473	      })
474	      .catch(() => {
475	        if (!cancelled) setStatus("failed");
476	      });
477	
478	    return () => {
479	      cancelled = true;
480	      resizeObserver?.disconnect();
481	      window.removeEventListener("resize", updateEmbedWidth);
482	      root.replaceChildren();
483	    };
484	  }, [embedHtml, shouldLoad]);
485	
486	  return (
487	    <div className="x-post-embed" data-x-status={status}>
488	      <div
489	        className={`x-post-native ${status === "ready" ? "is-ready" : ""}`}
490	        ref={nativeRef}
491	        aria-hidden={status !== "ready"}
492	      />
493	      {status !== "ready" && (
494	        <div className="x-post-fallback">
495	          {fallback}
496	          {!shouldLoad && (
497	            <button
498	              type="button"
499	              className="overlay-action-secondary x-post-load"
500	              onClick={() => setShouldLoad(true)}
501	            >
502	              Load post from X
503	            </button>
504	          )}
505	        </div>
506	      )}
507	    </div>
508	  );
509	}
