// Tiny CDP helper for spike/verification scripts (scratch, not committed).
import { mkdirSync } from "node:fs";
import { join } from "node:path";
export async function connect(port = "9333", out = "", match = "app://local/") {
  if (out) mkdirSync(out, { recursive: true });
  const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  const page = targets.find((t: any) => t.type === "page" && t.url.startsWith(match));
  const socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r, j) => { socket.onopen = r; socket.onerror = j; });
  let seq = 0;
  const pending = new Map<number, any>();
  const logs: string[] = [];
  socket.onmessage = (e) => {
    const m = JSON.parse(e.data as string);
    if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.j(new Error(m.error.message)) : p.r(m.result); return; }
    if (m.method === "Runtime.consoleAPICalled") logs.push(`[${m.params.type}] ${m.params.args.map((a: any) => a.value ?? a.description ?? "").join(" ")}`);
    if (m.method === "Runtime.exceptionThrown") logs.push(`[exception] ${m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text}`);
  };
  const send = (method: string, params: any = {}) => new Promise<any>((r, j) => { const id = ++seq; pending.set(id, { r, j }); socket.send(JSON.stringify({ id, method, params })); });
  await send("Runtime.enable");
  const ev = async (expression: string) => {
    const res = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    if (res.exceptionDetails) throw new Error(res.exceptionDetails.exception?.description ?? res.exceptionDetails.text);
    return res.result.value;
  };
  const until = async (expression: string, timeoutMs = 8000) => {
    const end = Date.now() + timeoutMs;
    while (Date.now() < end) { try { if (await ev(`Boolean(${expression})`)) return true; } catch {} await new Promise((r) => setTimeout(r, 100)); }
    throw new Error(`never held: ${expression}`);
  };
  const center = async (sel: string) => ev(`(() => { const r = document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return [r.left + r.width/2, r.top + r.height/2]; })()`);
  const move = async (x: number, y: number) => send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  const hover = async (sel: string) => { const [x, y] = await center(sel); await move(x, y); };
  const click = async (sel: string) => {
    const [x, y] = await center(sel);
    await move(x, y);
    await send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1 });
    await send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1 });
  };
  const KEYS: Record<string, any> = {
    Enter: { key: "Enter", code: "Enter", keyCode: 13, text: "\r" }, Escape: { key: "Escape", code: "Escape", keyCode: 27 },
    Tab: { key: "Tab", code: "Tab", keyCode: 9 }, ArrowDown: { key: "ArrowDown", code: "ArrowDown", keyCode: 40 },
    ArrowUp: { key: "ArrowUp", code: "ArrowUp", keyCode: 38 }, Space: { key: " ", code: "Space", keyCode: 32, text: " " },
  };
  const key = async (k: string, modifiers = 0) => {
    const d = KEYS[k] ?? { key: k, code: `Key${k.toUpperCase()}`, keyCode: k.toUpperCase().charCodeAt(0), text: k };
    await send("Input.dispatchKeyEvent", { type: d.text ? "keyDown" : "rawKeyDown", ...d, windowsVirtualKeyCode: d.keyCode, modifiers });
    await send("Input.dispatchKeyEvent", { type: "keyUp", ...d, windowsVirtualKeyCode: d.keyCode, modifiers });
  };
  const shot = async (name: string) => { const { data } = await send("Page.captureScreenshot", { format: "png" }); await Bun.write(join(out, name), Buffer.from(data, "base64")); };
  return { send, ev, until, hover, click, move, key, shot, logs, close: () => socket.close() };
}
