.licenses-back {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin: -6px 0 2px -8px;
  padding: 4px 10px 4px 6px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--color-muted);
  cursor: pointer;
  font: 400 12px / 16px var(--font-body);
  transition:
    background 0.18s ease,
    color 0.18s ease;
}
.licenses-back:hover {
  background: var(--color-glass-active);
  color: var(--color-ink);
}
.licenses-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: -16px;
}
.licenses-count {
  margin-right: auto;
  color: var(--color-muted);
  font: 400 12px / 16px var(--font-mono);
}
.licenses-search {
  width: min(260px, 50%);
  height: 34px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid #2e2a26;
  border-radius: 999px;
  color: var(--color-muted);
  transition: border-color 0.18s ease;
}
.licenses-search:focus-within {
  border-color: #4a443d;
}
.licenses-search input {
  min-width: 0;
  flex: 1 1 auto;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--color-ink);
  font: 400 13px / 16px var(--font-body);
}
.licenses-search input::placeholder {
  color: #5e5850;
}
.license-filter {
  position: relative;
  z-index: 2;
  flex: 0 1 auto;
  min-width: 0;
}
.license-filter-button {
  max-width: 100%;
  height: 34px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 12px 0 10px;
  border: 1px dashed #3a3530;
  border-radius: 999px;
  background: transparent;
  color: var(--color-ink-soft);
  cursor: pointer;
  font: 500 12px / 16px var(--font-body);
  white-space: nowrap;
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease;
}
.license-filter-button svg {
  flex: 0 0 auto;
  color: var(--color-muted);
}
.license-filter-button:hover:not(:disabled),
.license-filter-button[aria-expanded="true"] {
  border-color: #4a443d;
  background: var(--color-glass-active);
  color: var(--color-ink);
}
.license-filter-button:disabled {
  cursor: default;
  opacity: 0.5;
}
.license-filter-divider {
  width: 1px;
  height: 14px;
  margin: 0 2px;
  background: #3a3530;
}
.license-filter-badge {
  min-width: 0;
  overflow: hidden;
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--color-glass-active);
  color: var(--color-ink);
  font: 400 11px / 14px var(--font-mono);
  text-overflow: ellipsis;
}
/* Same surface as the context menu (ContextMenu.css). */
.license-filter-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  width: 250px;
  padding: 5px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-surface);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5);
  animation: license-filter-in 0.12s cubic-bezier(0.23, 1, 0.32, 1);
  transform-origin: top right;
}
@keyframes license-filter-in {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
}
.license-filter-options {
  max-height: 300px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #4a4842 transparent;
}
.license-filter-option,
.license-filter-clear {
  width: 100%;
  height: 32px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 10px 0 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--color-ink-soft);
  cursor: pointer;
  font: 13px var(--font-body);
  text-align: left;
}
.license-filter-option:is(:hover, :focus),
.license-filter-clear:is(:hover, :focus) {
  outline: 0;
  background: var(--color-glass-active);
  color: var(--color-ink);
}
.license-filter-check {
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  border: 1px solid #4a443d;
  border-radius: 4px;
  color: var(--color-frame);
}
.license-filter-option[aria-checked="true"] .license-filter-check {
  border-color: var(--color-ink);
  background: var(--color-ink);
}
.license-filter-label {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.license-filter-count {
  flex: 0 0 auto;
  color: var(--color-muted);
  font: 400 11px / 16px var(--font-mono);
}
.license-filter-clear {
  justify-content: center;
  color: var(--color-muted);
}
@media (prefers-reduced-motion: reduce) {
  .license-filter-menu {
    animation: none;
  }
}
.licenses-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.licenses-row {
  border-bottom: 1px solid #1e1b19;
  /* About two hundred rows; off-screen ones skip layout and paint. */
  content-visibility: auto;
  contain-intrinsic-size: auto 45px;
}
.licenses-row-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.licenses-row-toggle {
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 13px 2px;
  border: 0;
  background: transparent;
  color: var(--color-ink);
  cursor: pointer;
  text-align: left;
}
.licenses-chevron {
  flex: 0 0 auto;
  align-self: center;
  color: var(--color-muted);
  transition: rotate 0.18s ease;
}
.licenses-row[data-open] .licenses-chevron {
  rotate: 90deg;
}
.licenses-name {
  min-width: 0;
  overflow: hidden;
  font: 500 14px / 18px var(--font-body);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.licenses-version {
  flex: 0 0 auto;
  color: var(--color-muted);
  font: 400 12px / 16px var(--font-mono);
}
.licenses-id {
  min-width: 0;
  margin-left: auto;
  overflow: hidden;
  color: var(--color-ink-soft);
  font: 400 11px / 16px var(--font-mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.licenses-source {
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border-radius: 999px;
}
.licenses-source:hover {
  border-color: transparent;
  background: var(--color-glass-active);
  color: var(--color-ink);
}
.licenses-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 2px 16px 25px;
}
.licenses-body p {
  margin: 0;
  color: var(--color-muted);
  font: 400 13px / 19px var(--font-body);
}
.licenses-body pre {
  max-height: 320px;
  margin: 0;
  padding: 14px 16px;
  overflow: auto;
  border: 1px solid #221f1c;
  border-radius: 10px;
  background: var(--color-surface);
  color: var(--color-ink-soft);
  font: 400 11px / 17px var(--font-mono);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  scrollbar-width: thin;
  scrollbar-color: #4a4842 transparent;
}
.licenses-empty {
  margin: 0;
  padding: 20px 2px;
  color: var(--color-muted);
  font: 400 13px / 19px var(--font-body);
}

