  --breakpoint-wide: 781px;

  --animate-mascot-bob: mascot-bob 0.9s ease-in-out infinite;
  @keyframes mascot-bob {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-1.5px);
    }
  }
}

:root {
  --glass-filter: blur(18px) saturate(140%) brightness(0.7);
}

@layer base {
  :root {
    interpolate-size: allow-keywords;
    font-family: var(--font-body);
    color: var(--color-ink);
    background: var(--color-canvas);
    color-scheme: dark;
    font-synthesis: none;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  * {
    box-sizing: border-box;
  }
  html,
  body,
  #root {
    height: 100%;
  }
  body {
    margin: 0;
    min-width: 320px;
    min-height: 100vh;
    overflow: hidden;
  }
  button,
  input {
    font: inherit;
  }
  button {
    color: inherit;
    padding: 0;
  }
  /* Under the utilities layer, so a caller's border or fill always wins. */
  .ui-button {
    border: 0;
    background: none;
  }
}

