  const base = root.getBoundingClientRect();
  const walk = (e, path) => { const r = e.getBoundingClientRect();
    out.push(key + " " + path + " " + e.tagName + " rect=" + [r.x-base.x, r.y-base.y, r.width, r.height].map(v => Math.round(v*10)/10).join(",") + " " + fmt(getComputedStyle(e)));
