21	  const buttonRef = useRef<HTMLButtonElement>(null);
22	  const listRef = useRef<HTMLDivElement>(null);
23	
24	  useEffect(() => {
25	    if (!open) return;
26	    listRef.current?.querySelector<HTMLElement>("[role=menuitemcheckbox]")?.focus();
27	    const dismiss = (event: PointerEvent) => {
28	      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
29	      setOpen(false);
30	    };
31	    window.addEventListener("pointerdown", dismiss, true);
32	    return () => window.removeEventListener("pointerdown", dismiss, true);
33	  }, [open]);
34	
35	  const toggle = (license: string) => {
36	    const next = new Set(selected);
37	    if (!next.delete(license)) next.add(license);
38	    onChange(next);
39	  };
40	
41	  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
42	    const items = [...event.currentTarget.querySelectorAll<HTMLElement>("[role^=menuitem]")];
43	    const index = items.indexOf(document.activeElement as HTMLElement);
44	    const focusAt = (next: number) => items[(next + items.length) % items.length]?.focus();
45	    if (event.key === "ArrowDown") focusAt(index + 1);
46	    else if (event.key === "ArrowUp") focusAt(index - 1);
47	    else if (event.key === "Home") focusAt(0);
48	    else if (event.key === "End") focusAt(-1);
49	    else if (event.key === "Escape" || event.key === "Tab") {
50	      setOpen(false);
51	      buttonRef.current?.focus();
52	    } else return;
53	    event.preventDefault();
54	    event.stopPropagation();
