65	        aria-expanded={open}
66	        disabled={disabled}
67	        onClick={() => setOpen(!open)}
68	      >
69	        <HugeiconsIcon icon={PlusSignCircleIcon} size={14} />
70	        License
71	        {picked.length > 0 && (
72	          <>
73	            <span className="license-filter-divider" />
74	            {picked.length > MAX_BADGES ? (
75	              <span className="license-filter-badge">{picked.length} selected</span>
76	            ) : (
77	              picked.map(([license]) => (
78	                <span key={license} className="license-filter-badge">
79	                  {license}
80	                </span>
81	              ))
82	            )}
83	          </>
84	        )}
85	      </button>
86	      {open && (
87	        <div
88	          ref={listRef}
89	          className="license-filter-menu"
90	          role="menu"
91	          aria-label="Filter by license"
92	          onKeyDown={onKeyDown}
93	        >
94	          <div className="license-filter-options">
95	            {counts.map(([license, count]) => {
96	              const checked = selected.has(license);
97	              return (
98	                <button
99	                  key={license}
100	                  type="button"
101	                  role="menuitemcheckbox"
102	                  aria-checked={checked}
103	                  tabIndex={-1}
104	                  className="license-filter-option"
105	                  onClick={() => toggle(license)}
106	                >
107	                  <span className="license-filter-check">
108	                    {checked && <HugeiconsIcon icon={Tick02Icon} size={11} strokeWidth={2.4} />}
109	                  </span>
110	                  <span className="license-filter-label">{license}</span>
111	                  <span className="license-filter-count">{count}</span>
112	                </button>
113	              );
114	            })}
115	          </div>
116	          {selected.size > 0 && (
117	            <button
118	              type="button"
119	              role="menuitem"
120	              tabIndex={-1}
121	              className="license-filter-clear"
122	              onClick={() => {
123	                onChange(new Set());
124	                setOpen(false);
125	                buttonRef.current?.focus();
126	              }}
127	            >
128	              Clear filter
129	            </button>
130	          )}
131	        </div>
132	      )}
133	    </div>
134	  );
