1	import { Menu } from "@base-ui/react/menu";
2	import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react";
3	import { type RefObject, useEffect, useMemo, useRef } from "react";
4	
5	export type ContextMenuEntry = { label: string; icon: IconSvgElement; onSelect: () => void };
6	
7	type Props = {
8	  x: number;
9	  y: number;
10	  label: string;
11	  entries: ContextMenuEntry[];
12	  // Gets focus back when the menu is dismissed from the keyboard.
13	  returnFocus?: HTMLElement | null;
14	  // A layer App hands to liquid glass, so the menu takes the library's glass.
15	  container: RefObject<HTMLElement | null>;
16	  onClose: () => void;
17	};
18	
19	// Opens toward the pointer's bottom right, flipping on whichever axis would run
20	// off the window. Remount it (key) for each new pointer position.
21	export function ContextMenu({ x, y, label, entries, returnFocus, container, onClose }: Props) {
22	  const popupRef = useRef<HTMLDivElement>(null);
23	  const keyboardCloseRef = useRef(false);
24	  const openedRef = useRef(false);
25	  const anchor = useMemo(
26	    () => ({ getBoundingClientRect: () => DOMRect.fromRect({ x, y, width: 0, height: 0 }) }),
27	    [x, y],
28	  );
29	
30	  useEffect(() => {
31	    const dismiss = (event: Event) => {
32	      if (event.target instanceof Node && popupRef.current?.contains(event.target)) return;
33	      onClose();
34	    };
35	    window.addEventListener("wheel", dismiss, { capture: true, passive: true });
36	    window.addEventListener("resize", onClose);
37	    window.addEventListener("blur", onClose);
38	    return () => {
39	      window.removeEventListener("wheel", dismiss, true);
40	      window.removeEventListener("resize", onClose);
41	      window.removeEventListener("blur", onClose);
42	    };
43	  }, [onClose]);
44	
45	  return (
46	    <Menu.Root
47	      open
48	      modal={false}
49	      onOpenChange={(open, details) => {
50	        if (open) return;
51	        keyboardCloseRef.current = details.reason === "escape-key";
52	        onClose();
53	      }}
54	    >
55	      <Menu.Portal container={container}>
56	        <Menu.Positioner
57	          anchor={anchor}
58	          positionMethod="fixed"
59	          side="bottom"
60	          align="start"
61	          collisionPadding={8}
62	          collisionAvoidance={{ side: "flip", align: "flip", fallbackAxisSide: "none" }}
63	          className="z-1000"
64	        >
65	          <Menu.Popup
66	            ref={popupRef}
67	            aria-label={label}
68	            finalFocus={() => (keyboardCloseRef.current ? (returnFocus ?? false) : false)}
69	            onFocus={(event) => {
70	              // A pointer open lands Base UI's focus on the popup after mount; the
71	              // first item takes it instead, so it opens highlighted.
72	              if (openedRef.current || event.target !== event.currentTarget) return;
73	              openedRef.current = true;
74	              event.currentTarget
75	                .querySelector<HTMLElement>("[role=menuitem]")
76	                ?.focus({ preventScroll: true });
77	            }}
78	            className="glass min-w-[200px] max-w-[280px] rounded-[12px] p-[5px] outline-none transition-[opacity,transform] duration-120 ease-[cubic-bezier(0.23,1,0.32,1)] data-starting-style:opacity-0 data-starting-style:[transform:scale(0.97)] motion-reduce:transition-none"
79	            onKeyDown={(event) => {
80	              if (event.key !== "Tab") return;
81	              event.preventDefault();
82	              onClose();
83	              returnFocus?.focus({ preventScroll: true });
84	            }}
85	            onContextMenu={(event) => event.preventDefault()}
86	          >
87	            {entries.map((entry) => (
88	              <Menu.Item
89	                key={entry.label}
90	                className="flex h-8 w-full cursor-pointer items-center gap-2.5 rounded-[8px] py-0 pr-2.5 pl-2 text-left font-body text-[13px] leading-[normal] whitespace-nowrap text-ink-soft outline-none data-highlighted:bg-glass-active data-highlighted:text-ink [&_svg]:flex-none [&_svg]:text-muted data-highlighted:[&_svg]:text-ink"
91	                onClick={entry.onSelect}
92	              >
93	                <HugeiconsIcon icon={entry.icon} size={15} />
94	                {entry.label}
95	              </Menu.Item>
96	            ))}
97	          </Menu.Popup>
98	        </Menu.Positioner>
99	      </Menu.Portal>
100	    </Menu.Root>
101	  );
102	}
