6	// packages/ui is AGPL.
7	
8	import { useLayoutEffect, useRef, useState } from "react";
9	import "./SegmentedControl.css";
10	
11	export type SegmentedControlOption<Value extends string> = {
12	  value: Value;
13	  label: string;
14	};
15	
16	export function SegmentedControl<Value extends string>({
17	  name,
18	  label,
19	  options,
20	  value,
21	  onChange,
22	  className,
23	}: {
24	  /** Groups the radios, so it must be unique on the page. */
25	  name: string;
26	  /** Read by screen readers; not shown. */
27	  label: string;
28	  options: readonly SegmentedControlOption<Value>[];
29	  value: Value;
30	  onChange: (value: Value) => void;
31	  className?: string;
32	}) {
33	  const rootRef = useRef<HTMLFieldSetElement>(null);
34	  const [indicator, setIndicator] = useState<{ left: number; width: number } | null>(null);
35	
36	  useLayoutEffect(() => {
37	    const root = rootRef.current;
38	    if (!root) return;
39	    const measure = () => {
40	      const item = root.querySelector<HTMLElement>(`[data-value="${CSS.escape(value)}"]`);
41	      setIndicator(item ? { left: item.offsetLeft, width: item.offsetWidth } : null);
42	    };
43	    measure();
44	    const observer = new ResizeObserver(measure);
45	    observer.observe(root);
46	    return () => observer.disconnect();
47	  }, [value]);
48	
49	  return (
50	    <fieldset ref={rootRef} className={`segmented-control${className ? ` ${className}` : ""}`}>
51	      <legend className="visually-hidden">{label}</legend>
52	      <span
53	        className="segmented-control-indicator"
54	        aria-hidden="true"
55	        hidden={!indicator}
56	        style={{ translate: `${indicator?.left ?? 0}px 0`, width: indicator?.width }}
57	      />
58	      {options.map((option) => (
59	        <label
60	          key={option.value}
61	          className="segmented-control-item"
62	          data-value={option.value}
63	          data-checked={option.value === value || undefined}
64	        >
65	          <input
66	            type="radio"
67	            className="visually-hidden"
68	            name={name}
69	            value={option.value}
70	            checked={option.value === value}
71	            onChange={() => onChange(option.value)}
72	          />
73	          <span>{option.label}</span>
74	        </label>
75	      ))}
76	    </fieldset>
77	  );
78	}
