1	import { useEffect, useRef, useState } from "react";
2	import {
3	  getAppVersion,
4	  getLastExport,
5	  getLibrarySize,
6	  isDesktopRuntime,
7	  type LastExport,
8	  type LibrarySize,
9	  listActiveItems,
10	} from "../../lib/libraryApi";
11	import type { ItemKind } from "../../lib/types";
12	import { keepTabFocusInside } from "../../ui/keepTabFocusInside";
13	import { cardKind } from "../library/libraryItem";
14	import { useAppearance } from "./appearance";
15	
16	type SettingsOptions = {
17	  canUseDesktopBackend: boolean;
18	  activeSpaceId: string | null;
19	  debouncedQuery: string;
20	};
21	
22	export function useSettings({
23	  canUseDesktopBackend,
24	  activeSpaceId,
25	  debouncedQuery,
26	}: SettingsOptions) {
27	  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
28	  const [settingsTab, setSettingsTab] = useState<
29	    "general" | "licenses" | "appearance" | "archive" | "data" | "extension"
30	  >("general");
31	  const [appearance, setAppearanceOption] = useAppearance();
32	  const [appVersion, setAppVersion] = useState<string | null>(null);
33	  const [librarySizeBytes, setLibrarySizeBytes] = useState<number | null>(null);
34	  // In the desktop app an open Space or search narrows `items`, so Settings
35	  // counts the whole library on its own. Null means `items` already is it.
36	  const [wholeLibraryKinds, setWholeLibraryKinds] = useState<ItemKind[] | null>(null);
37	  const [lastCopy, setLastCopy] = useState<LastExport | null>(null);
38	  const settingsDialogRef = useRef<HTMLElement>(null);
39	
40	  useEffect(() => {
41	    if (!isSettingsOpen) return;
42	
43	    const previouslyFocused =
44	      document.activeElement instanceof HTMLElement ? document.activeElement : null;
45	    // Focus the dialog itself, not a control, so the sheet opens without a ring.
46	    const focusTimer = window.setTimeout(() => settingsDialogRef.current?.focus(), 0);
47	
48	    const onSettingsKeyDown = (event: KeyboardEvent) => {
49	      const modal = document.querySelector<HTMLElement>(".settings-modal");
50	      if (modal) keepTabFocusInside(event, modal);
51	    };
52	
53	    document.addEventListener("keydown", onSettingsKeyDown);
54	    return () => {
55	      window.clearTimeout(focusTimer);
56	      document.removeEventListener("keydown", onSettingsKeyDown);
57	      previouslyFocused?.focus();
58	    };
59	  }, [isSettingsOpen]);
60	
61	  useEffect(() => {
62	    if (!isSettingsOpen) setSettingsTab("general");
63	  }, [isSettingsOpen]);
64	
65	  // Version, size and last copy are optional: each stays hidden when the
66	  // desktop backend cannot supply it (preview, or a failed call). The size
67	  // walks every asset file, so Settings shows the last measured value at once
68	  // and replaces it when a fresh walk finishes, without holding up the rest.
69	  useEffect(() => {
70	    if (!isSettingsOpen || !isDesktopRuntime()) return;
71	    let cancelled = false;
72	    void Promise.all([
73	      getAppVersion().catch(() => undefined),
74	      getLastExport().catch(() => undefined),
75	    ]).then(([version, copy]) => {
76	      if (cancelled) return;
77	      setAppVersion(version ?? null);
78	      setLastCopy(copy ?? null);
79	    });
80	    const showSize = (size: LibrarySize | undefined) => {
81	      if (!cancelled && size) setLibrarySizeBytes(size.bytes);
82	    };
83	    // Fired together so a first open, with nothing cached yet, shares one walk.
84	    void getLibrarySize().then(showSize, () => undefined);
85	    void getLibrarySize(true).then(showSize, () => undefined);
86	    return () => {
87	      cancelled = true;
88	    };
89	  }, [isSettingsOpen]);
90	
91	  const isLibraryNarrowed = Boolean(activeSpaceId) || debouncedQuery.trim() !== "";
92	  useEffect(() => {
93	    if (!isSettingsOpen || !canUseDesktopBackend || !isLibraryNarrowed) {
94	      setWholeLibraryKinds(null);
95	      return;
96	    }
97	    let cancelled = false;
98	    void listActiveItems().then(
99	      (cards) => {
100	        if (!cancelled) setWholeLibraryKinds(cards.map(cardKind));
101	      },
102	      () => undefined,
103	    );
104	    return () => {
105	      cancelled = true;
106	    };
107	  }, [canUseDesktopBackend, isLibraryNarrowed, isSettingsOpen]);
108	
109	  const isArchiveTabOpen = isSettingsOpen && settingsTab === "archive";
110	
111	  return {
112	    isSettingsOpen,
113	    setIsSettingsOpen,
114	    settingsTab,
115	    setSettingsTab,
116	    isArchiveTabOpen,
117	    appearance,
118	    setAppearanceOption,
119	    appVersion,
120	    librarySizeBytes,
121	    wholeLibraryKinds,
122	    lastCopy,
123	    setLastCopy,
124	    settingsDialogRef,
125	  };
126	}
