    <div className="flex items-center gap-[18px] px-0.5 py-5 [&:not(:last-of-type)]:border-b [&:not(:last-of-type)]:border-[#1e1b19]">
      <span
        className="grid size-9 flex-none place-items-center rounded-[11px] bg-surface-raised text-ink"
