await c.send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await c.ev(`window.__stale = true; true`);
await c.send("Page.navigate", { url });
await c.until(`!window.__stale && document.querySelectorAll(".library-card").length > 3`, 15000);
const settle = async () => { for (let i = 0; i < 6; i++) await c.ev(`new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))`); };
const M = "[role='dialog'][aria-labelledby]";
const info = () => c.ev(`(() => ({ tiles: document.querySelectorAll("${M} .library-card").length, note: document.querySelector("#archive-panel-title")?.closest("header")?.querySelector("p")?.textContent ?? null, tabCount: document.querySelector('[role=tab]:nth-child(4)')?.textContent, everything: document.querySelector('[aria-label="Settings"]') && [...document.querySelectorAll("nav *, aside *")].find(e => e.textContent?.trim().startsWith("Everything") && e.children.length > 1)?.textContent }))()`);
const clickText = async (sel: string, text: string) => {
  const ok = await c.ev(`(() => { const e = [...document.querySelectorAll(${JSON.stringify(sel)})].find(e => e.textContent.trim() === ${JSON.stringify(text)} || e.getAttribute("aria-label") === ${JSON.stringify(text)}); if (!e) return false; e.setAttribute("data-probe", "1"); return true; })()`);
  if (!ok) throw new Error(`no ${sel} ${text}`);
  await c.click("[data-probe]");
  await c.ev(`document.querySelector("[data-probe]")?.removeAttribute("data-probe"); true`);
  await settle();
};
const log: unknown[] = [];
await c.click('button[aria-label="Settings"]');
await c.until(`document.querySelector('aside[aria-label="Settings sections"]')`);
await clickText("[role=tab]", "Archive3");
