await c.shot("tile-selected.png");
await clickText(`${M} button`, "Delete");
log.push(["deleted", await info()]);
await clickText(`${M} button`, "Exit multi-select mode");
await c.key("Escape"); await settle();
log.push(["restored card in library", await c.ev(`[...document.querySelectorAll(".library-card")].some(e => e.textContent.includes(${JSON.stringify(title)}))`)]);
console.log(JSON.stringify(log, null, 0).replaceAll("],[", "],\n["));
console.log(c.logs.filter((l) => /error|exception/i.test(l)).slice(0, 8));
c.close();

