// Symmetric full-app shots for base vs branch: seed 4 notes, archive 2, shoot every Settings tab.
import { connect } from "../squ129/cdp";
const [port, out] = process.argv.slice(2);
const c = await connect(port, out, "app://local/");
await c.send("Page.bringToFront");
await c.send("Emulation.setFocusEmulationEnabled", { enabled: true });
const settle = async (n = 6) => { for (let i = 0; i < n; i++) await c.ev(`new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))`); };
const D = "#settings-modal";
const probe = async (expr: string) => { await c.ev(`(${expr}).setAttribute("data-probe","1"); true`); };
const unprobe = () => c.ev(`document.querySelector("[data-probe]")?.removeAttribute("data-probe"); true`);
const clickProbe = async (expr: string) => { await probe(expr); await c.click("[data-probe]"); await unprobe(); };
const noToasts = async () => { await c.move(5, 400); await c.ev(`document.querySelectorAll("[data-sonner-toast] [data-close-button]").forEach(b => b.click()); true`); await c.until(`!document.querySelector("[data-sonner-toast]")`, 20000); };
await c.until(`document.querySelector("button[data-tooltip='Add something to your library']")`, 20000);
for (let i = 0; i < 4; i++) {
  await c.click("button[data-tooltip='Add something to your library']"); await settle();
  await clickProbe(`[...document.querySelectorAll(".add-menu-tile")].find(e => e.textContent.includes("Note"))`);
  await c.until(`document.querySelector("textarea[aria-label='New note']")`);
  await c.ev(`document.querySelector("textarea[aria-label='New note']").focus(); true`);
  await c.send("Input.insertText", { text: `parity note ${i}` });
  await c.click("button.add-menu-save");
  await c.until(`document.querySelectorAll('article.library-card').length === ${i + 1}`, 10000);
  await settle();
}
for (let i = 0; i < 2; i++) {
  const [x, y] = await c.ev(`(() => { const r = document.querySelector("article.library-card").getBoundingClientRect(); return [r.left + r.width/2, r.top + r.height/2]; })()`);
  await c.move(x, y);
  await c.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "right", clickCount: 1 });
  await c.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "right", clickCount: 1 });
  await c.until(`[...document.querySelectorAll("[role=menuitem]")].some(e => e.textContent.trim() === "Archive")`);
  await clickProbe(`[...document.querySelectorAll("[role=menuitem]")].find(e => e.textContent.trim() === "Archive")`);
  await c.until(`document.querySelectorAll('article.library-card').length === ${3 - i}`, 10000);
  await settle();
}
await noToasts();
await c.click('button[aria-label="Settings"]');
await c.until(`document.querySelector("${D}")`); await settle(12);
const tab = async (label: string) => {
  await clickProbe(`[...document.querySelectorAll("${D} aside button")].find(e => e.textContent.trim().startsWith(${JSON.stringify(label)}))`);
  await settle(12);
};
await c.move(5, 700);
await c.shot("general.png");
await clickProbe(`[...document.querySelectorAll("${D} button")].find(e => e.textContent.trim() === "View licenses")`);
await c.until(`document.querySelectorAll("${D} li, ${D} article").length > 5`, 10000).catch(() => {});
await settle(12); await c.shot("licenses.png");
await tab("Appearance"); await c.shot("appearance.png");
await tab("Library"); await settle(20); await c.shot("library.png");
await tab("Browser extension");
await c.until(`/Listening/.test(document.querySelector("${D}").innerText)`, 8000).catch(() => {});
await settle(); await c.shot("extension.png");
await tab("Archive");
await c.until(`document.querySelectorAll("${D} .library-card").length === 2`, 10000); await settle(12);
await c.shot("archive.png");
await c.hover(`${D} .library-card`); await settle(); await c.shot("archive-hover.png");
