  height: 100%;
  max-height: none;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.expanded-overlay-layer.is-focus-mode .item-close {
  position: fixed;
  top: 22px;
  right: 28px;
  width: auto;
  min-width: 92px;
  padding: 0 12px;
  border-color: #38332e;
  border-radius: 999px;
  background: var(--color-surface-raised);
  color: #c8c0b5;
  font: 11px var(--font-body);
}
.expanded-overlay-layer.is-focus-mode .item-close:hover {
  border-color: #6b5748;
  background: #25211e;
}
/* Focus mode covers the whole window, so Exit focus must clear the band the
   window controls use in the desktop app. */
.electron-shell .expanded-overlay-layer.is-focus-mode .item-close {
  top: calc(4px + var(--spacing-titlebar));
}
.expanded-overlay.is-editing-note .item-stage {
  display: none;
}
.expanded-overlay.is-editing-note .item-inspector {
  left: var(--item-inset);
  width: auto;
  padding: 6px 0 0;
}
.expanded-overlay.is-editing-note .item-inspector-header {
  padding-inline: 16px;
}
.expanded-overlay.is-editing-note .item-inspector-body {
  gap: 0;
  padding: 0;
  overflow: hidden;
}
.note-embedded-editor {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  margin: 0;
}
.note-embedded-orientation {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 12px 20px;
  border-bottom: 1px solid #1f1d1b;
}
.note-embedded-kicker {
  flex: 0 0 auto;
  color: #6f6a62;
  font: 10px var(--font-body);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.note-embedded-divider {
  flex: 0 0 auto;
  width: 1px;
  height: 11px;
  background: #332f2c;
}
.note-embedded-name {
