/* Item view: covers the library frame, stage on the left and inspector on
   the right. While it flies from or back to its card (.is-flying) the stage
   fills the whole rectangle and the inspector hides, so the card reads as its
   own image growing into the frame. */
.expanded-overlay-layer {
  position: fixed;
  inset: 0;
  z-index: 6;
  pointer-events: none;
}
.app-shell.settings-open .expanded-overlay-layer {
  z-index: 130;
}
/* Paper's frame has no border of its own. A border here would offset the stage
   and inspector by a pixel, so the viewer and inspector insets would not match. */
.expanded-overlay {
  /* The stage fills the frame less one even gap; the window controls sit over
     the inspector, so only the inspector drops below their band. Both share a
     bottom, so the action bar ends on the stage's bottom edge. */
  --item-inset: 8px;
  --item-inspector-top: calc(3px + var(--spacing-titlebar));
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  overflow: hidden;
  border-radius: calc(var(--radius-frame) - 1px) 0 0 calc(var(--radius-frame) - 1px);
  background: var(--color-frame);
  pointer-events: auto;
}
.expanded-overlay.is-flying {
  will-change: left, top, width, height, opacity;
}
.item-stage {
  position: absolute;
  inset: var(--item-inset) 320px var(--item-inset) var(--item-inset);
  display: grid;
  place-items: center;
  padding: 60px 40px;
  overflow: hidden;
  border: 1px solid var(--color-border);
  border-radius: calc(var(--radius-frame) - 1px - var(--item-inset) + 4px);
  --item-stage-surface:
    radial-gradient(circle, #2a2623 1px, transparent 1.2px) 0 0 / 18px 18px #121110;
  background: var(--item-stage-surface);
  transition:
    inset 0.32s cubic-bezier(0.2, 0.8, 0.2, 1),
    padding 0.32s cubic-bezier(0.2, 0.8, 0.2, 1),
    border-radius 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.expanded-overlay.is-flying .item-stage {
  inset: 0;
  padding: 0;
  border-color: transparent;
  border-radius: inherit;
}
/* The view mounts in its resting layout for a moment before the open flight
   starts, so the stage must not ease from there into the card. */
.expanded-overlay.is-opening .item-stage {
  transition: none;
}
.item-stage-image {
  position: absolute;
  top: 50%;
  left: 50%;
  display: block;
  max-width: 100%;
  max-height: 100%;
  translate: -50% -50%;
  border-radius: 4px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
}
.expanded-overlay.is-flying .item-stage-image {
