const calm = `document.getAnimations().every(a => a.playState !== "running" || a.effect?.getTiming().iterations === Infinity)`;
const settle = async () => {
  for (let i = 0; i < 6; i++) await c.ev(`new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))`);
  await c.until(calm, 15000);
  await c.ev(`Promise.all([...document.images].filter(i => !i.complete).map(i => new Promise(r => { i.onload = i.onerror = r; })))`);
