async function openItem(id: string) {
  // The grid is virtualized: scroll until the card is mounted.
  await c.ev(`(async () => {
    const scroller = [...document.querySelectorAll("*")].find(e => e.scrollHeight > e.clientHeight + 20 && getComputedStyle(e).overflowY !== "visible" && e.querySelector(".library-card"));
    for (let y = 0; y < 40000 && !${card(id)}; y += 400) { scroller.scrollTop = y; await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))); }
    ${card(id)}.scrollIntoView({ block: "center" });
    return true;
  })()`);
  await settle();
  await c.ev(`${card(id)}.focus(); true`);
  await c.key("Enter");
  await c.until(`document.activeElement?.getAttribute("aria-label") === "Close details"`, 8000);
  await settle();
}
