const [a, b] = process.argv.slice(2);
const A = await sharp(a).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
const B = await sharp(b).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
const { width, height } = A.info;
const cell = 40;
const cells = new Map();
for (let y = 0; y < height; y++)
  for (let x = 0; x < width; x++) {
    const i = (y * width + x) * 4;
    let d = 0;
    for (let k = 0; k < 3; k++) d = Math.max(d, Math.abs(A.data[i + k] - B.data[i + k]));
    if (d > 8) {
      const key = `${Math.floor(x / cell) * cell},${Math.floor(y / cell) * cell}`;
      cells.set(key, (cells.get(key) ?? 0) + 1);
    }
  }
