import { connect } from "../squ129/cdp";
const [port, out] = process.argv.slice(2);
const c = await connect(port, out, "app://local/");
await c.send("Page.bringToFront");
await c.send("Emulation.setFocusEmulationEnabled", { enabled: true });
await c.send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
const log: Record<string, unknown> = {};
const frames = (n = 6) => c.ev(`new Promise(r => { let i = 0; const f = () => (++i >= ${n} ? r(true) : requestAnimationFrame(f)); requestAnimationFrame(f); })`);
const calm = `document.getAnimations().every(a => a.playState !== "running" || a.effect?.getTiming().iterations === Infinity)`;
const settle = async () => {
  await frames(8);
  await c.until(calm, 15000);
  await c.ev(`Promise.all([...document.images].filter(i => !i.complete).map(i => new Promise(r => { i.onload = i.onerror = r; })))`);
  await frames(4);
};
const dismissToasts = () => c.ev(`document.querySelectorAll("[data-sonner-toast] [data-close-button]").forEach(b => b.click()); true`);
const probe = async (expr: string) => c.ev(`(${expr}).setAttribute("data-probe","1"); true`);
const clickProbe = async (expr: string) => {
  await probe(expr);
  await c.click("[data-probe]");
  await c.ev(`document.querySelector("[data-probe]")?.removeAttribute("data-probe"); true`);
};
const cardFor = (text: string) => `[...document.querySelectorAll('article.library-card')].find(a => a.textContent.includes(${JSON.stringify(text)}))`;

await c.until(`document.querySelector("button[data-tooltip='Add something to your library']")`, 20000);

// Seed: an image and a PDF through paste, a note and a quote through the Add menu.
const paste = (make: string, name: string, type: string) =>
  c.ev(`(async () => {
    const blob = await (${make})();
    const dt = new DataTransfer();
    dt.items.add(new File([blob], ${JSON.stringify(name)}, { type: ${JSON.stringify(type)} }));
    document.body.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true }));
    return true;
  })()`);
await paste(`() => { const cv = document.createElement("canvas"); cv.width = 1600; cv.height = 1000; const g = cv.getContext("2d");
  const grad = g.createLinearGradient(0, 0, 1600, 1000); grad.addColorStop(0, "#c46b3c"); grad.addColorStop(1, "#2f5d62"); g.fillStyle = grad; g.fillRect(0, 0, 1600, 1000);
  for (let x = 0; x < 1600; x += 8) for (let y = 0; y < 1000; y += 8) if (((x + y) / 8) % 7 === 0) { g.fillStyle = "rgba(255,255,255,0.35)"; g.fillRect(x, y, 4, 4); }
  g.fillStyle = "#fff"; g.font = "bold 120px sans-serif"; g.fillText("squ131 image", 260, 540);
  return new Promise(r => cv.toBlob(r, "image/png")); }`, "squ131-image.png", "image/png");
await c.until(`${cardFor("squ131-image")}`, 15000);
const pdf = `%PDF-1.4
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 6 0 R >> >> >> endobj
4 0 obj << /Length 66 >> stream
BT /F1 32 Tf 72 700 Td (squ131 pdf page one) Tj ET
endstream endobj
5 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 7 0 R /Resources << /Font << /F1 6 0 R >> >> >> endobj
6 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj
7 0 obj << /Length 66 >> stream
BT /F1 32 Tf 72 700 Td (squ131 pdf page two) Tj ET
endstream endobj
trailer << /Root 1 0 R >>
%%EOF`;
await paste(`async () => new Blob([${JSON.stringify(pdf)}], { type: "application/pdf" })`, "squ131-paper.pdf", "application/pdf");
await c.until(`${cardFor("squ131-paper")}`, 15000);
const addMenu = async (tile: string) => {
  await dismissToasts();
  await c.click("button[data-tooltip='Add something to your library']");
  await settle();
  await clickProbe(`[...document.querySelectorAll(".add-menu-tile")].find(e => e.textContent.includes(${JSON.stringify(tile)}))`);
};
await addMenu("Note");
await c.until(`document.querySelector("textarea[aria-label='New note']")`);
await c.ev(`document.querySelector("textarea[aria-label='New note']").focus(); true`);
await c.send("Input.insertText", { text: "squ131 note\n\nA few lines about the item view so the editor has something to hold." });
await c.click("button.add-menu-save");
await c.until(`${cardFor("squ131 note")}`, 10000);
await addMenu("Quote");
await c.until(`document.querySelector("[aria-label='Quote text']")`);
await c.ev(`document.querySelector("[aria-label='Quote text']").focus(); true`);
await c.send("Input.insertText", { text: "squ131 quote: the view should feel like the card grew." });
await c.ev(`document.querySelector("[aria-label='Quote attribution']").focus(); true`);
await c.send("Input.insertText", { text: "A tester" });
await c.click("button.add-menu-save");
await c.until(`${cardFor("squ131 quote")}`, 10000);

// A Regular Space to file things in.
await c.click("button[aria-label='Add a Space']");
await c.until(`document.querySelector("input[aria-label='Space name']")`);
await c.ev(`document.querySelector("input[aria-label='Space name']").focus(); true`);
await c.send("Input.insertText", { text: "Moodboard" });
await c.key("Enter");
await c.until(`[...document.querySelectorAll("nav *, aside *")].some(e => e.textContent === "Moodboard")`, 8000);

// Wait for thumbnails, then a calm grid.
await c.until(`${cardFor("squ131-image")}?.querySelector("img")?.complete && ${cardFor("squ131-paper")}?.querySelector("img, canvas")`, 30000).catch(() => (log.pdfThumb = "missing"));
await dismissToasts();
await settle();
await c.shot("00-library.png");

const open = async (text: string) => {
  await dismissToasts();
  await c.ev(`${cardFor(text)}.focus(); true`);
  await c.key("Enter");
  await c.until(`document.activeElement?.getAttribute("aria-label") === "Close details"`, 8000);
  await settle();
};
const close = async () => {
  await c.ev(`document.querySelector('button[aria-label="Close details"]')?.focus(); true`);
  await c.key("Escape");
  await c.until(`!document.querySelector(".expanded-overlay")`, 8000);
  await settle();
};
const view = (expr: string) => c.ev(`(() => { const v = document.querySelector(".expanded-overlay"); return ${expr}; })()`);

for (const [text, name] of [["squ131-image", "image"], ["squ131-paper", "pdf"], ["squ131 note", "note"], ["squ131 quote", "quote"]]) {
  await open(text);
  await c.shot(`${name}-info.png`);
  log[`${name}`] = await view(`({ label: v.getAttribute("aria-label"), buttons: [...v.querySelectorAll("button")].map(b => b.getAttribute("aria-label") || b.textContent.trim()).filter(Boolean) })`);
  await close();
  log[`${name}-focus-after-close`] = await c.ev(`document.activeElement?.textContent?.slice(0, 30)`);
}

// Image: zoom swaps in the original, pixel zoom shows the grid, no shadow while zoomed.
await open("squ131-image");
const stageImg = `v.querySelector("img")`;
log.zoomRest = await view(`({ src: ${stageImg}.src.slice(0, 60), shadow: getComputedStyle(${stageImg}).boxShadow.includes("24px 60px") && !getComputedStyle(${stageImg}).boxShadow.endsWith("rgba(0, 0, 0, 0) 0px 0px 0px 0px"), glass: document.querySelectorAll(".glass[data-liquid]").length, canvases: document.querySelectorAll("canvas").length })`);
for (let i = 0; i < 2; i++) await c.click('button[aria-label="Zoom in"]');
await c.until(`(() => { const v = document.querySelector(".expanded-overlay"); return ${stageImg}.src !== ${JSON.stringify("")} && !${stageImg}.src.includes("thumb"); })()`, 8000).catch(() => undefined);
await settle();
await c.shot("image-zoom.png");
log.zoomed = await view(`({ src: ${stageImg}.src.slice(0, 80), label: v.querySelector('button[aria-label="Zoom in"]').previousElementSibling.textContent, shadow: getComputedStyle(${stageImg}).boxShadow })`);
for (let i = 0; i < 12; i++) await c.click('button[aria-label="Zoom in"]');
await settle();
await c.shot("image-pixel-zoom.png");
log.pixel = await view(`({ label: v.querySelector('button[aria-label="Zoom in"]').previousElementSibling.textContent, rendering: getComputedStyle(${stageImg}).imageRendering, grid: [...v.querySelectorAll("div")].some(d => getComputedStyle(d).backgroundImage.includes("linear-gradient")) })`);
// Drag pans the zoomed image.
const before = await view(`${stageImg}.style.transform`);
const [cx, cy] = await view(`(() => { const r = ${stageImg}.parentElement.getBoundingClientRect(); return [r.left + r.width / 2, r.top + r.height / 2]; })()`);
await c.move(cx, cy);
await c.send("Input.dispatchMouseEvent", { type: "mousePressed", x: cx, y: cy, button: "left", clickCount: 1 });
await c.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: cx + 120, y: cy + 60, button: "left", buttons: 1 });
await c.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: cx + 120, y: cy + 60, button: "left", clickCount: 1 });
log.pan = { before, after: await view(`${stageImg}.style.transform`) };
await close();

// Spaces: the menu toggles membership, and the chip follows it.
await open("squ131-image");
await c.click('button[aria-label="Move to Space"]');
await settle();
await c.shot("space-menu.png");
log.menu = await c.ev(`({ role: document.querySelector("[role=menu]") ? "menu" : "fieldset", focus: document.activeElement?.textContent?.trim(), checked: document.activeElement?.getAttribute("aria-checked") ?? document.activeElement?.getAttribute("aria-pressed") })`);
await c.key("Enter");
await settle();
log.afterToggle = await c.ev(`({ menuOpen: Boolean(document.querySelector("[role=menu], fieldset")), chip: [...document.querySelectorAll(".expanded-overlay span")].some(s => s.textContent === "Moodboard"), checked: [...document.querySelectorAll("[role=menuitemcheckbox], fieldset button")].map(e => e.getAttribute("aria-checked") ?? e.getAttribute("aria-pressed")) })`);
await c.shot("space-member.png");
await c.key("Escape");
await settle();
log.afterEscape = { view: await c.ev(`Boolean(document.querySelector(".expanded-overlay"))`), focus: await c.ev(`document.activeElement?.getAttribute("aria-label")`) };
await c.shot("space-chip.png");

// Tags.
if (await c.ev(`Boolean(document.querySelector(".expanded-overlay"))`)) {
  await c.click('button[aria-label="Add a tag"]');
  await c.until(`document.activeElement?.getAttribute("aria-label") === "New tag name"`);
  await c.send("Input.insertText", { text: "squ131tag" });
  await c.key("Enter");
  await settle();
  log.tag = await view(`[...v.querySelectorAll("span")].some(s => s.textContent === "#squ131tag")`);
  // Similar tab via keyboard.
  await c.ev(`[...document.querySelectorAll(".expanded-overlay [role=tab]")].find(t => t.textContent === "Info").focus(); true`);
  await c.key("ArrowRight");
  await settle();
  log.similarTab = await c.ev(`document.querySelector(".expanded-overlay [role=tab][aria-selected=true]")?.textContent`);
  await c.shot("image-similar.png");
  await close();
}

// PDF viewer from the item view.
await open("squ131-paper");
await clickProbe(`[...document.querySelectorAll(".expanded-overlay button")].find(b => b.textContent.includes("Open PDF"))`);
await c.until(`document.querySelector('[aria-label="Close PDF viewer"]') && [...document.querySelectorAll("canvas")].some(cv => !cv.hidden && cv.width > 100 && cv.closest("section[aria-modal=true]"))`, 15000).catch(() => (log.pdfViewer = "no canvas"));
await settle();
await c.shot("pdf-viewer.png");
log.pdfPage = await c.ev(`document.querySelector('input[aria-label="Page number"]')?.parentElement?.textContent`);
await c.click('button[aria-label="Next page"]');
await settle();
log.pdfPage2 = await c.ev(`document.querySelector('input[aria-label="Page number"]')?.value`);
await c.click('button[aria-label="Close viewer"]');
await c.until(`!document.querySelector('[aria-label="Close PDF viewer"]')`, 8000);
await settle();
log.afterPdfClose = await c.ev(`Boolean(document.querySelector(".expanded-overlay"))`);
await close();

// Note: the editor keeps full height in a narrow window, then archive from the view.
await open("squ131 note");
await clickProbe(`[...document.querySelectorAll(".expanded-overlay button")].find(b => b.textContent.trim() === "Edit note")`);
await c.until(`document.querySelector(".note-embedded-editor")`, 8000);
await c.send("Emulation.setDeviceMetricsOverride", { width: 640, height: 800, deviceScaleFactor: 1, mobile: false });
await settle();
await c.shot("note-edit-narrow.png");
log.narrowEditor = await c.ev(`(() => { const r = document.querySelector(".note-embedded-editor").getBoundingClientRect(); return [Math.round(r.top), Math.round(r.height)]; })()`);
await c.send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await settle();
await clickProbe(`[...document.querySelectorAll(".expanded-overlay button")].find(b => b.textContent.trim() === "Focus mode")`);
await settle();
await c.shot("note-focus.png");
log.focusClose = await c.ev(`(() => { const r = document.querySelector('button[aria-label="Exit focus mode"]').getBoundingClientRect(); return [r.top, r.right, r.height]; })()`);
await c.key("Escape");
await settle();
await c.key("Escape");
await settle();
log.backToInfo = await c.ev(`document.activeElement?.getAttribute("aria-label") ?? document.activeElement?.tagName`);
await c.click('button[aria-label="Archive"]');
await c.until(`!document.querySelector(".expanded-overlay")`, 8000);
await settle();
log.noteCardGone = await c.ev(`!${cardFor("squ131 note")}`);
log.logs = c.logs.filter((l) => !l.startsWith("[debug]") && !l.includes("DevTools"));
await Bun.write(`${out}/report.json`, JSON.stringify(log, null, 2));
console.log(JSON.stringify(log, null, 2));
c.close();

