cat > "$TEMP/squ131/composite.mjs" <<'EOF'
import sharp from "sharp";
const [dir, out, ...names] = process.argv.slice(2);
const w = 640, h = 400, gap = 8;
const tiles = [];
for (const [r, n] of names.entries())
  for (const [c, side] of ["full-before", "full-after"].entries())
    tiles.push({ input: await sharp(`${dir}/${side}/${n}.png`).resize(w, h).png().toBuffer(), left: c * (w + gap), top: r * (h + gap) });
await sharp({ create: { width: w * 2 + gap, height: names.length * (h + gap) - gap, channels: 4, background: "#ffffff" } }).composite(tiles).png().toFile(out);
EOF
