"""Remove named test()/describe() blocks from a test file.

usage: drop_tests.py FILE NAME [NAME...]
Each NAME is the exact first argument string of a test( or describe( call.
"""
import re
import sys


def block_end(s: str, start: int) -> int:
    i = s.index("(", start)
    depth = 0
    quote = None
    while i < len(s):
        ch = s[i]
        if quote:
            if ch == "\\":
                i += 2
                continue
            if ch == quote:
                quote = None
        elif ch in "\"'`":
            quote = ch
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                end = i + 1
                if s[end : end + 1] == ";":
                    end += 1
                if s[end : end + 1] == "\n":
                    end += 1
                return end
        i += 1
    raise SystemExit("unbalanced")


path, *names = sys.argv[1:]
s = open(path, encoding="utf-8").read()
for name in names:
    m = re.search(r"^[ \t]*(?:test|describe)(?:\.each\([^\n]*?\))?\(\s*" + re.escape(json_name := '"' + name + '"'), s, re.M)
    if not m:
        raise SystemExit(f"not found: {name}")
    start = m.start()
    end = block_end(s, start)
    # drop one blank line left behind
    if s[end : end + 1] == "\n" and (start == 0 or s[start - 2 : start] == "\n\n"):
        end += 1
    s = s[:start] + s[end:]
open(path, "w", encoding="utf-8", newline="\n").write(s)

